DELIMITER $$
CREATE PROCEDURE sp_rows(OUT n INT)
BEGIN
  DECLARE sid CHAR(10);
  DECLARE done INT DEFAULT 0;
  DECLARE cur CURSOR FOR SELECT Sno FROM S;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
  SET n = 0;
  OPEN cur;
  FETCH cur INTO sid;
  WHILE done = 0 DO
    SET n = n + 1;
    FETCH cur INTO sid;
  END WHILE;
  CLOSE cur;
END $$
DELIMITER ;

