DELIMITER $$
CREATE PROCEDURE sp_grade_level(IN sid CHAR(10),
  IN cid CHAR(6), OUT lv VARCHAR(10))
BEGIN
  DECLARE g INT;
  SELECT Grade INTO g FROM SC
    WHERE Sno = sid AND Cno = cid;
  CASE
    WHEN g >= 90 THEN SET lv = '优秀';
    WHEN g >= 75 THEN SET lv = '良好';
    WHEN g >= 60 THEN SET lv = '及格';
    ELSE SET lv = '不及格';
  END CASE;
END $$
DELIMITER ;
CALL sp_grade_level('2024001', 'C01', @lv);
SELECT @lv;
DROP PROCEDURE IF EXISTS sp_grade_level;

