CREATE PROCEDURE sp_add_credit(INOUT total INT, IN cid CHAR(6))
BEGIN
  DECLARE c INT DEFAULT 0;
  SELECT Credit INTO c FROM C WHERE Cno = cid;
  SET total = total + c;
END $$
